/**
 * The campus map: a tall scrolling map. Ground, road and scenery are drawn in Skia from seamless
 * tiles and decoration sprites; the buildings on top are tappable sprites; Kip walks the road
 * between them, facing the way he's going. Tapping a building walks Kip there, then opens it.
 * The ground is drawn in screen-sized chunks so no single canvas outgrows a phone's texture limit.
 * Art: ./sprites.ts (generated by scripts/process_campus.py) and the kipMap* clips in @/art/anims.
 */
import { BlurMask, Canvas, Circle, DashPathEffect, Group, Image as SkiaImage, ImageShader, LinearGradient, Oval, Path, Rect, rect, Skia, useImage, vec, type SkImage } from '@shopify/react-native-skia';
import { Image } from 'expo-image';
import { useEffect, useMemo, useState, type Ref } from 'react';
import { Animated, Pressable, ScrollView, StyleSheet, Text, View, type ScrollViewInstance } from 'react-native';
import { useReducedMotion } from 'react-native-reanimated';

import { ANIMS, type SpriteAnimation } from '@/art/anims';
import { WORLDS, type Track } from '@/content';
import { createRng } from '@/sim/rng';
import { colors, shadow, type } from '@/ui/theme';

import { decoList, spriteFor } from './art';
import { LABEL_H, placeBox, SPRITE_W } from './layout';
import { doorOf, MAP_HEIGHT, pathLength, PLACES, roadSegments, spurFor, type Place, type Pt, type SpotId, type SpotState, type WorldStatus } from './map';
import { AMBIENT, AMBIENT_ANIM, ambientBox, scatterScenery } from './scenery';
import type { Skin, SkinId } from './skins';
import { GROUND_TILES } from './sprites';
import { facingSchedule, facingTimes, type Facing } from './walk';

const KIP_H = 0.15; // Kip's height on the map, in screen widths
const KIP_DY = 0.035; // Kip walks a little below the road's centre line, so he stands in front of a building's base
const ROAD_W = 0.08;

export interface CampusMapProps {
  width: number;
  skin: Skin;
  track: Track;
  worldStatus: Record<string, WorldStatus>;
  /** "3/5" style progress per world. */
  worldProgress: Record<string, { done: number; total: number; next?: string }>;
  spots: Record<SpotId, SpotState & { isNew: boolean }>;
  /** Where Kip is standing (a road stop: 'gate' or a world id). */
  kipAt: string;
  /** Set while Kip walks; the map animates him along this path. */
  walk: { pts: Pt[]; durationMs: number } | null;
  walkProgress: Animated.Value;
  /** The map is on screen (its tab is focused); animations pause otherwise. */
  active: boolean;
  highlight?: string;
  onPressPlace: (p: Place) => void;
  scrollRef: Ref<ScrollViewInstance>;
  onViewport: (height: number) => void;
  /** Called once the map has its full size (safe to scroll). */
  onReady: () => void;
}

export function CampusMap(props: CampusMapProps) {
  const { width: W, skin, scrollRef, onViewport, onReady } = props;
  const H = MAP_HEIGHT * W;
  const chunks = Math.ceil(MAP_HEIGHT);
  const scene = useMemo(() => buildScene(W, skin.id), [W, skin.id]);
  const art = useMapArt(skin.id);
  // Which half-screen band the map is scrolled to, so only the ambient loops near the view animate.
  // It changes every half screen of scrolling, not on every scroll event.
  const [band, setBand] = useState(0);
  const [viewH, setViewH] = useState(W * 2);
  const view = { top: band * W * 0.5 - W * 0.5, bottom: band * W * 0.5 + viewH + W * 0.5 };
  return (
    <ScrollView
      ref={scrollRef}
      onLayout={(e) => {
        setViewH(e.nativeEvent.layout.height);
        onViewport(e.nativeEvent.layout.height);
      }}
      onScroll={(e) => {
        const b = Math.round(e.nativeEvent.contentOffset.y / (W * 0.5));
        if (b !== band) setBand(b);
      }}
      scrollEventThrottle={120}
      onContentSizeChange={onReady}
      showsVerticalScrollIndicator={false}
      contentContainerStyle={{ height: H }}
      testID="campus-map">
      <View style={{ width: W, height: H, backgroundColor: skin.ground.edge ?? skin.ground.bottom }}>
        {Array.from({ length: chunks }, (_, i) => (
          // Keyed by look, so switching track (campus ↔ island) redraws the ground, and by whether the
          // art has loaded: a canvas that is off screen when the images arrive can miss that redraw.
          <Canvas key={`${skin.id}-${i}-${art.ready ? 'art' : 'plain'}`} style={{ position: 'absolute', left: 0, top: i * W, width: W, height: Math.min(W, H - i * W) }} pointerEvents="none">
            <Group transform={[{ translateY: -i * W }]}>
              <Ground W={W} H={H} skin={skin} scene={scene} art={art} />
              <Scenery items={scene.deco.filter((d) => d.y - d.h < (i + 1) * W && d.y + 0.03 * W > i * W)} art={art} />
            </Group>
          </Canvas>
        ))}
        <Ambient W={W} skin={skin.id} sky={false} active={props.active} view={view} />
        {PLACES.map((p) => (
          <PlaceTile key={p.id} place={p} {...props} />
        ))}
        <Walker {...props} />
        <Ambient W={W} skin={skin.id} sky active={props.active} view={view} />
      </View>
    </ScrollView>
  );
}

// ---- Art ---------------------------------------------------------------------------------

interface MapArt {
  lawn: SkImage | null;
  path: SkImage | null;
  grass: SkImage | null;
  sand: SkImage | null;
  water: SkImage | null;
  deco: Record<string, SkImage | null>;
  /** Every tile and decoration has loaded. */
  ready: boolean;
}

function useMapArt(skin: SkinId): MapArt {
  const lawn = useImage(GROUND_TILES.campusLawn);
  const path = useImage(GROUND_TILES.campusPath);
  const grass = useImage(GROUND_TILES.islandGrass);
  const sand = useImage(GROUND_TILES.islandSand);
  const water = useImage(GROUND_TILES.islandWater);
  // Six decorations per look (three trees, three props), always in the same order.
  const list = decoList(skin);
  const d = [useImage(list[0].sprite.src), useImage(list[1].sprite.src), useImage(list[2].sprite.src), useImage(list[3].sprite.src), useImage(list[4].sprite.src), useImage(list[5].sprite.src)];
  const deco = Object.fromEntries(list.map((x, i) => [x.id, d[i]]));
  const ready = [lawn, path, grass, sand, water, ...d].every(Boolean);
  return { lawn, path, grass, sand, water, deco, ready };
}

/** A seamless tile repeated over the shape it's placed in; `size` is one tile's side in points. */
function Tile({ image, size }: { image: SkImage; size: number }) {
  return <ImageShader image={image} tx="repeat" ty="repeat" fit="fill" rect={rect(0, 0, size, size)} />;
}

// ---- Ground, road and scenery (Skia) ------------------------------------------------------

interface Deco {
  id: string;
  /** Bottom centre, in points. */
  x: number;
  y: number;
  w: number;
  h: number;
}

function buildScene(W: number, skin: SkinId) {
  const roadB = Skia.PathBuilder.Make();
  roadSegments().forEach((s, i) => {
    if (i === 0) roadB.moveTo(s.from.x * W, s.from.y * W);
    roadB.cubicTo(s.c1.x * W, s.c1.y * W, s.c2.x * W, s.c2.y * W, s.to.x * W, s.to.y * W);
  });
  const road = roadB.detach();
  const spurB = Skia.PathBuilder.Make();
  for (const p of PLACES.filter((x) => x.kind === 'spot')) {
    const { from, to } = spurFor(p);
    spurB.moveTo(from.x * W, from.y * W);
    spurB.lineTo(to.x * W, to.y * W);
  }
  const spurs = spurB.detach();

  const deco: Deco[] = scatterScenery(skin).map((d) => ({ id: d.id, x: d.x * W, y: d.y * W, w: d.w * W, h: d.h * W }));
  const rng = createRng(skin === 'campus' ? 5 : 7);
  const patches = Array.from({ length: 24 }, () => ({ x: rng() * W, y: rng() * MAP_HEIGHT * W, r: (0.1 + rng() * 0.14) * W }));
  return { road, spurs, deco, patches };
}

type Scene = ReturnType<typeof buildScene>;

function Ground({ W, H, skin, scene, art }: { W: number; H: number; skin: Skin; scene: Scene; art: MapArt }) {
  const roadW = ROAD_W * W;
  const gradient = <LinearGradient start={vec(0, 0)} end={vec(0, H)} colors={[skin.ground.top, skin.ground.bottom]} />;
  return (
    <>
      {skin.ground.edge !== null ? (
        <>
          {/* Sea, a soft white shoreline, a sand strip along the road with a clearing at every stop, then grass. */}
          <Rect x={0} y={0} width={W} height={H} color={skin.ground.edge} />
          {art.water ? (
            <Rect x={0} y={0} width={W} height={H}>
              <Tile image={art.water} size={0.5 * W} />
            </Rect>
          ) : null}
          <Path path={scene.road} style="stroke" strokeWidth={0.72 * W} strokeCap="round" strokeJoin="round" color="rgba(255,255,255,0.6)">
            <BlurMask blur={10} style="normal" />
          </Path>
          <Land scene={scene} W={W} stroke={0.66} radius={0.9} image={art.sand} tile={0.32 * W} fallback={skin.ground.patch} />
          <Land scene={scene} W={W} stroke={0.54} radius={0.76} image={art.grass} tile={0.62 * W} fallback={skin.ground.top} />
        </>
      ) : (
        <>
          <Rect x={0} y={0} width={W} height={H}>
            {gradient}
          </Rect>
          {art.lawn ? (
            <Rect x={0} y={0} width={W} height={H}>
              <Tile image={art.lawn} size={0.42 * W} />
            </Rect>
          ) : null}
          {scene.patches.map((p, i) => (
            <Circle key={i} cx={p.x} cy={p.y} r={p.r} color={skin.ground.patch} opacity={0.22}>
              <BlurMask blur={24} style="normal" />
            </Circle>
          ))}
        </>
      )}
      {/* A soft shadow under every building, so the sprites sit on the ground. */}
      {PLACES.map((p) => {
        const w = SPRITE_W[p.kind] * W;
        const bottom = placeBox(p, 1).bottom * W;
        return (
          <Oval key={`sh-${p.id}`} x={p.x * W - w * 0.47} y={bottom - w * 0.24} width={w * 0.94} height={w * 0.3} color="rgba(30,42,58,0.22)">
            <BlurMask blur={8} style="normal" />
          </Oval>
        );
      })}
      {/* Spurs to the activity spots, then the main road: an edge, then the paving. */}
      <Path path={scene.spurs} style="stroke" strokeWidth={roadW * 0.72} strokeCap="round" color={skin.road.edge} />
      <Road path={scene.spurs} width={roadW * 0.54} image={skin.ground.edge === null ? art.path : art.sand} tile={0.16 * W} fallback={skin.road.fill} />
      <Path path={scene.road} style="stroke" strokeWidth={roadW} strokeCap="round" strokeJoin="round" color={skin.road.edge} />
      <Road path={scene.road} width={roadW * 0.8} image={skin.ground.edge === null ? art.path : art.sand} tile={0.16 * W} fallback={skin.road.fill} />
      {skin.ground.edge !== null ? (
        // Island: stepping stones down the middle of the sandy path.
        <Path path={scene.road} style="stroke" strokeWidth={6} strokeCap="round" color="rgba(150,112,70,0.45)">
          <DashPathEffect intervals={[0.1, 18]} />
        </Path>
      ) : null}
    </>
  );
}

/** The island's land: a wide stroke along the road plus a round clearing at every stop, filled with one tile. */
function Land({ scene, W, stroke, radius, image, tile, fallback }: { scene: Scene; W: number; stroke: number; radius: number; image: SkImage | null; tile: number; fallback: string }) {
  const fill = (key: string) => (image ? <Tile key={key} image={image} size={tile} /> : null);
  return (
    <>
      <Path path={scene.road} style="stroke" strokeWidth={stroke * W} strokeCap="round" strokeJoin="round" color={fallback}>
        {fill('road')}
      </Path>
      {PLACES.map((p) => (
        <Circle key={p.id} cx={p.x * W} cy={(p.y + 0.06) * W} r={p.size * radius * W} color={fallback}>
          {fill(p.id)}
        </Circle>
      ))}
    </>
  );
}

function Road({ path, width, image, tile, fallback }: { path: Scene['road']; width: number; image: SkImage | null; tile: number; fallback: string }) {
  return (
    <Path path={path} style="stroke" strokeWidth={width} strokeCap="round" strokeJoin="round" color={fallback}>
      {image ? <Tile image={image} size={tile} /> : null}
    </Path>
  );
}

function Scenery({ items, art }: { items: Deco[]; art: MapArt }) {
  return (
    <>
      {items.map((d, i) => {
        const img = art.deco[d.id];
        if (!img) return null;
        return (
          <Group key={i}>
            <Oval x={d.x - d.w * 0.42} y={d.y - d.w * 0.12} width={d.w * 0.84} height={d.w * 0.22} color="rgba(30,42,58,0.16)">
              <BlurMask blur={4} style="normal" />
            </Oval>
            <SkiaImage image={img} x={d.x - d.w / 2} y={d.y - d.h} width={d.w} height={d.h} fit="contain" />
          </Group>
        );
      })}
    </>
  );
}

// ---- Buildings and spots (React Native, so they're tappable and accessible) ---------------

function PlaceTile({ place: p, width: W, skin, worldStatus, worldProgress, spots, highlight, onPressPlace }: CampusMapProps & { place: Place }) {
  const lit = highlight === p.id;
  // The gate is Money Town (World 0): the first building, open from day one.
  const worldId = p.kind === 'gate' ? 'w0' : p.kind === 'world' ? p.id : null;
  const status = worldId ? worldStatus[worldId] : undefined;
  const spot = p.kind === 'spot' ? spots[p.id as SpotId] : undefined;
  const closed = status === 'locked' || status === 'builderOnly' || (spot ? !spot.unlocked : false);
  const pulse = usePulse(lit || status === 'current');
  const sprite = spriteFor(skin.id, p.id, closed)!;
  const box = placeBox(p, sprite.aspect);
  const w = box.w * W;
  const h = box.h * W;
  const labelH = LABEL_H[p.kind] * W;
  const outer = Math.max(w, 0.36 * W); // room for the label, which can be wider than a spot
  const frame = { position: 'absolute' as const, left: p.x * W - outer / 2, top: box.labelTop * W, width: outer, alignItems: 'center' as const };

  const art = (
    <Animated.View style={{ width: w, height: h, transform: [{ scale: pulse }] }}>
      <Image source={sprite.src} style={{ width: w, height: h }} contentFit="contain" accessible={false} />
      {closed ? <Chip text="🔒" style={{ right: w * 0.08, bottom: h * 0.12 }} /> : null}
      {status === 'done' ? <Chip text="✓" gold style={{ right: w * 0.06, top: h * 0.18 }} /> : null}
    </Animated.View>
  );

  if (spot) {
    const id = p.id as SpotId;
    const copy = skin.spots[id];
    return (
      <Pressable
        testID={`spot-${id}`}
        onPress={() => onPressPlace(p)}
        accessibilityRole="button"
        accessibilityLabel={`${copy.name}: ${copy.activity}. ${spot.unlocked ? (spot.badge ? `${spot.badge} waiting.` : 'Open.') : 'Locked.'}`}
        style={frame}>
        <View style={{ height: labelH, justifyContent: 'flex-end', paddingBottom: 4, alignItems: 'center' }}>
          <Text style={[type.tiny, styles.sign, { color: spot.unlocked ? colors.ink : colors.inkMuted }]} numberOfLines={1}>
            {copy.emoji} {copy.name}
          </Text>
        </View>
        {art}
        {spot.badge ? <Badge text={spot.badge} top={labelH + h * 0.12} right={(outer - w) / 2 + w * 0.06} /> : spot.isNew ? <Badge text="NEW" color={colors.kip} top={labelH + h * 0.12} right={(outer - w) / 2 + w * 0.06} /> : null}
      </Pressable>
    );
  }

  const world = WORLDS.find((x) => x.id === worldId)!;
  const prog = worldProgress[world.id];
  const copy = skin.places[world.id];
  const starting = status === 'current' && (prog?.done ?? 0) === 0;
  const sub =
    status === 'done'
      ? '★ Complete'
      : starting
        ? '👉 Start here'
        : status === 'current'
          ? `Next: ${prog?.next ?? ''}`
          : status === 'builderOnly'
            ? 'Builder track · 16+'
            : status === 'locked'
              ? '🔒 Locked'
              : `${prog?.done ?? 0}/${prog?.total ?? 0} lessons`;
  return (
    <Pressable testID={`place-${p.id}`} onPress={() => onPressPlace(p)} accessibilityRole="button" accessibilityLabel={`World ${world.index}, ${copy.name}: ${world.title}. ${sub}.`} style={frame}>
      <View style={{ height: labelH, justifyContent: 'flex-end', paddingBottom: 4, maxWidth: outer }}>
        <View style={[styles.label, { borderWidth: status === 'current' ? 2 : 0, borderColor: colors.kip }]}>
          <Text style={[type.tiny, { color: closed ? colors.inkMuted : colors.ink, fontWeight: '800' }]} numberOfLines={1}>
            {world.index} · {copy.name}
          </Text>
          <Text style={[type.tiny, { fontSize: 11, color: status === 'current' ? colors.kipDark : colors.inkSoft }]} numberOfLines={1}>
            {sub}
          </Text>
        </View>
      </View>
      {art}
    </Pressable>
  );
}

function Chip({ text, gold, style }: { text: string; gold?: boolean; style: object }) {
  return (
    <View style={[{ position: 'absolute', width: 26, height: 26, borderRadius: 13, alignItems: 'center', justifyContent: 'center', backgroundColor: gold ? colors.shell : '#fff', borderWidth: 2, borderColor: '#fff', ...shadow }, style]}>
      <Text style={{ fontSize: gold ? 13 : 12, fontWeight: '900', color: colors.ink }}>{text}</Text>
    </View>
  );
}

function Badge({ text, color = colors.error, top, right }: { text: string; color?: string; top: number; right: number }) {
  return (
    <View style={{ position: 'absolute', top, right, backgroundColor: color, borderRadius: 999, paddingHorizontal: 7, paddingVertical: 2, borderWidth: 2, borderColor: '#fff' }}>
      <Text style={{ color: '#fff', fontSize: 11, fontWeight: '900' }}>{text}</Text>
    </View>
  );
}

function usePulse(on: boolean) {
  const [v] = useState(() => new Animated.Value(1));
  useEffect(() => {
    if (!on) return;
    const loop = Animated.loop(Animated.sequence([Animated.timing(v, { toValue: 1.04, duration: 800, useNativeDriver: true }), Animated.timing(v, { toValue: 1, duration: 800, useNativeDriver: true })]));
    loop.start();
    return () => {
      loop.stop();
      v.setValue(1);
    };
  }, [on, v]);
  return v;
}

// ---- Ambient loops (flags, fountains, gulls) ------------------------------------------------

/** The little animated touches. Ground ones sit under the buildings; gulls fly above everything. */
function Ambient({ W, skin, sky, active, view }: { W: number; skin: SkinId; sky: boolean; active: boolean; view: { top: number; bottom: number } }) {
  return (
    <>
      {AMBIENT[skin]
        .filter((a) => (a.kind === 'seagulls') === sky)
        .map((a, i) => {
          const b = ambientBox(a);
          return (
            <View key={`${a.kind}-${i}`} pointerEvents="none" accessible={false} style={{ position: 'absolute', left: b.x0 * W, top: b.y0 * W, width: (b.x1 - b.x0) * W, height: (b.y1 - b.y0) * W }}>
              {/* Same clip in several places, started at different frames so they don't move in step. */}
              <Frames anim={AMBIENT_ANIM[a.kind]} size={(b.x1 - b.x0) * W} height={(b.y1 - b.y0) * W} offset={i * 7} mirror={a.kind === 'flag' && a.x > 0.5} paused={!active || b.y1 * W < view.top || b.y0 * W > view.bottom} />
            </View>
          );
        })}
    </>
  );
}

// ---- Kip ----------------------------------------------------------------------------------

const WALK_CLIPS: Record<Facing['view'], SpriteAnimation> = { up: ANIMS.kipMapUp, down: ANIMS.kipMapDown, side: ANIMS.kipMapSide };

/** Kip on the map: idling at his stop, or walking the road facing the way he's going. */
function Walker({ width: W, kipAt, walk, walkProgress, active }: CampusMapProps) {
  const h = KIP_H * W;
  const box = h * 1.1; // square box; each clip is fitted inside, feet on the bottom edge
  const motion = useMemo(() => {
    if (!walk) return null;
    // At most ~48 points keeps the native interpolation light.
    const step = Math.max(1, Math.ceil(walk.pts.length / 48));
    const pts = walk.pts.filter((_, i) => i % step === 0 || i === walk.pts.length - 1);
    const input = pts.map((_, i) => i / (pts.length - 1));
    return {
      x: walkProgress.interpolate({ inputRange: input, outputRange: pts.map((p) => p.x * W - box / 2) }),
      y: walkProgress.interpolate({ inputRange: input, outputRange: pts.map((p) => (p.y + KIP_DY) * W - box * 0.94) }),
      schedule: facingSchedule(pts),
    };
  }, [walk, walkProgress, W, box]);
  const facing = useFacing(motion?.schedule ?? null, walk?.durationMs ?? 0);
  const stand = doorOf(PLACES.find((p) => p.id === kipAt) ?? PLACES[0]);
  const style = motion ? { transform: [{ translateX: motion.x }, { translateY: motion.y }] } : { transform: [{ translateX: stand.x * W - box / 2 }, { translateY: (stand.y + KIP_DY) * W - box * 0.94 }] };
  const clip = motion && facing ? WALK_CLIPS[facing.view] : ANIMS.kipMapIdle;
  return (
    <Animated.View pointerEvents="none" style={[{ position: 'absolute', left: 0, top: 0, width: box, height: box }, style]} accessible accessibilityLabel="Kip">
      <View style={{ position: 'absolute', left: box * 0.22, bottom: -2, width: box * 0.56, height: box * 0.16, borderRadius: box, backgroundColor: 'rgba(30,42,58,0.2)' }} />
      {/* Not keyed by clip: swapping the source in place keeps the last frame up while the next clip loads, so Kip never blinks out. */}
      <Frames anim={clip} size={box} mirror={!!(motion && facing?.mirror)} paused={!active} />
    </Animated.View>
  );
}

/** Follows the walk's progress and returns the facing in effect (changes only at the schedule's turns). */
/**
 * Which way Kip faces right now. The turns are timed from the walk's duration and easing, so
 * nothing has to listen to the native animation frame by frame.
 */
function useFacing(schedule: ReturnType<typeof facingSchedule> | null, durationMs: number): Facing | undefined {
  // Tied to its walk, so a new walk never starts with the last walk's facing.
  const [turn, setTurn] = useState<{ walk: object | null; facing?: Facing }>({ walk: null });
  useEffect(() => {
    if (!schedule) return;
    const timers = facingTimes(schedule, durationMs).map((t) => setTimeout(() => setTurn({ walk: schedule, facing: t.facing }), t.ms));
    return () => timers.forEach(clearTimeout);
  }, [schedule, durationMs]);
  if (!schedule) return undefined;
  return turn.walk === schedule ? turn.facing : schedule[0]?.facing;
}

/** Plays a sprite animation in a square box, feet on the bottom edge. Holds the first frame with reduced motion. */
function Frames({ anim, size, height = size, mirror = false, offset = 0, paused = false }: { anim: SpriteAnimation; size: number; height?: number; mirror?: boolean; offset?: number; paused?: boolean }) {
  const reduce = useReducedMotion();
  const [frame, setFrame] = useState(offset);
  useEffect(() => {
    if (reduce || paused) return;
    const id = setInterval(() => setFrame((f) => (f + 1) % anim.frames.length), 1000 / anim.fps);
    return () => clearInterval(id);
  }, [reduce, paused, anim]);
  return (
    <Image
      source={anim.frames[frame % anim.frames.length]}
      style={{ width: size, height, transform: mirror ? [{ scaleX: -1 }] : undefined }}
      contentFit="contain"
      contentPosition="bottom"
      cachePolicy="memory"
    />
  );
}

/** How long Kip takes to walk a path (seconds per screen width of road), clamped. */
export function walkDuration(pts: Pt[]): number {
  return Math.min(2600, Math.max(600, pathLength(pts) * 1600));
}

const styles = StyleSheet.create({
  sign: { backgroundColor: '#fff', borderRadius: 999, paddingHorizontal: 8, paddingVertical: 3, overflow: 'hidden', fontWeight: '800' },
  label: { backgroundColor: '#fff', borderRadius: 12, paddingHorizontal: 10, paddingVertical: 4, alignItems: 'center', maxWidth: '100%', ...shadow },
});
